  function wireFilter(type){const search=$('#list-search'),filter=$('#list-filter');const update=()=>{const q=search.value.toLowerCase(),status=filter.value;const list=(type==='tasks'?cache.tasks:cache.products).filter(x=>(!status||x.status===status)&&((x.title||x.name||'').toLowerCase().includes(q)||(x.description||'').toLowerCase().includes(q)));$('#list-results').innerHTML=type==='tasks'?taskRows(list):productCards(list)};search.addEventListener('input',update);filter.addEventListener('change',update)}
  function wireBusinessProfile(){const form=$('#business-profile-form');form?.addEventListener('submit',async e=>{e.preventDefault();if(!['owner','admin'].includes(membership?.role)){toast('Only company owners and admins can edit this profile.',true);return}const fd=new FormData(form),payload={};for(const key of ['name','business_category','motto','contact_email','contact_phone','address','website_url','logo_url','cover_image_url']){const value=String(fd.get(key)||'').trim();payload[key]=value||null}const submit=$('button[type="submit"]',form);submit.disabled=true;submit.textContent='Saving profile…';const {data,error}=await supabase.from('company_profiles').update(payload).eq('id',company.id).select().maybeSingle();submit.disabled=false;submit.innerHTML='Save business details <span>→</span>';if(error){toast(error.message,true);return}if(data)company={...company,...data};$('#sidebar-company').textContent=company.name;toast('Business profile saved.');renderPage('business-profile')});const upload=$('#gallery-upload-form');upload?.addEventListener('submit',async e=>{e.preventDefault();if(!['owner','admin'].includes(membership?.role))return;const files=[...($('#gallery-files')?.files||[])],status=$('#gallery-upload-status'),submit=$('button[type="submit"]',upload);if(!files.length)return;for(const file of files){if(!/^image\/(jpeg|png|webp|gif|avif)$/.test(file.type)||file.size>8*1024*1024){toast('Choose supported images no larger than 8 MB each.',true);return}}submit.disabled=true;submit.textContent='Uploading…';if(status)status.textContent='Uploading '+files.length+' image(s)…';const gallery=Array.isArray(company.gallery_images)?[...company.gallery_images]:[];for(const file of files){const safeName=file.name.normalize('NFKD').replace(/[^a-zA-Z0-9._-]+/g,'-').slice(-90)||'business-image';const path=company.id+'/'+crypto.randomUUID()+'-'+safeName;const {error}=await supabase.storage.from('business-gallery').upload(path,file,{contentType:file.type,upsert:false});if(error){toast('Image upload stopped: '+error.message,true);if(status)status.textContent='Some images may have uploaded. Refresh the page to check.';submit.disabled=false;submit.innerHTML='Upload to gallery <span>↑</span>';return}const {data}=supabase.storage.from('business-gallery').getPublicUrl(path);gallery.push({url:data.publicUrl,path,caption:($('#gallery-caption')?.value||'').trim(),uploaded_at:new Date().toISOString()})}const {data,error}=await supabase.from('company_profiles').update({gallery_images:gallery}).eq('id',company.id).select().maybeSingle();submit.disabled=false;submit.innerHTML='Upload to gallery <span>↑</span>';if(error){toast('Images uploaded, but gallery save failed: '+error.message,true);return}if(data)company={...company,...data};toast('Business gallery updated.');renderPage('business-profile')})}
  document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){navigate(nav.dataset.page);return}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='remove-gallery-image'){const index=Number(e.target.closest('[data-action]').dataset.index);if(!Number.isInteger(index)||index<0)return;const gallery=Array.isArray(company.gallery_images)?[...company.gallery_images]:[];const item=gallery[index];if(!item)return;if(!confirm('Remove this image from the business gallery?'))return;(async()=>{const next=gallery.filter((_,i)=>i!==index);const {data,error}=await supabase.from('company_profiles').update({gallery_images:next}).eq('id',company.id).select().maybeSingle();if(error){toast(error.message,true);return}if(item.path)await supabase.storage.from('business-gallery').remove([item.path]);company={...company,...(data||{}),gallery_images:next};toast('Image removed from gallery.');renderPage('business-profile')})()}if(action==='create-task')openForm('task');if(action==='create-operation')openForm('operation',e.target.closest('[data-action]')?.dataset.operationType||'');if(action==='create-school-class')openForm('school-class');if(action==='create-school-learner')openForm('school-learner');if(action==='create-school-assessment')openForm('school-assessment');if(action==='create-school-fee')openForm('school-fee');if(action==='create-stock-movement')openForm('stock-movement');if(action==='create-product')openForm('product');if(action==='create-announcement')openForm('announcement');if(action==='create-department')openForm('department');if(action==='create-invitation')openForm('invitation');if(action==='create-customer')openForm('customer');if(action==='create-inventory')openForm('inventory');if(action==='create-sale')openForm('sale');if(action==='create-finance')openForm('finance');if(action==='create-attendance')openForm('attendance');if(action==='create-report')openForm('report');if(action==='create-council')openForm('council');if(action==='create-website-request')openForm('website-request');if(action==='create-website-payment')openForm('website-payment');if(action==='verify-website-payment'){const id=e.target.closest('[data-action]').dataset.id;if(confirm('Mark this installment as verified? Only do this after checking the payment reference.'))(async()=>{const {error}=await supabase.from('website_service_payments').update({verification_status:'verified',verified_by:user.id,verified_at:new Date().toISOString()}).eq('id',id);if(error)toast(error.message,true);else{toast('Payment marked verified.');await refreshData();renderPage(currentPage)}})()}if(action==='save-preferences')savePreferences(false);if(action==='reset-preferences')savePreferences(true);if(action==='reconfigure'){if(confirm('Disconnect this browser from the current Supabase project?')){localStorage.removeItem(CONFIG_KEY);location.reload()}}});
  function operationTypesForCategory(){const c=(company?.business_category||'other').toLowerCase();const groups=[{match:['education','school'],items:[['school_class','Class / class activity','Record a class, stream, timetable or class activity'],['student_record','Learner record','Track a non-sensitive learner administration follow-up'],['assessment','Assessment / examination','Record assessment, marks workflow or exam preparation'],['school_fee','School fee follow-up','Record fee follow-up or payment administration']]},{match:['healthcare','clinic','pharmacy'],items:[['appointment','Appointment','Schedule and follow up a service appointment'],['client_visit','Client visit','Record a minimal visit summary; avoid unnecessary sensitive details'],['purchase','Medical supplies purchase','Record approved supply purchases'],['work_order','Equipment / service work order','Track repairs and service jobs']]},{match:['retail','wholesale','manufacturing','automotive'],items:[['purchase','Stock purchase','Record incoming stock purchase'],['stock_adjustment','Stock adjustment','Record a stock count discrepancy or correction'],['sales_return','Sales return','Record returned goods'],['work_order','Production / work order','Track production or operational work']]},{match:['agriculture','farming'],items:[['farm_activity','Farm activity','Record planting, treatment, irrigation or field work'],['harvest','Harvest / produce collection','Record harvest quantities and outcomes'],['purchase','Inputs purchase','Record seed, feed, fertilizer or tool purchases']]},{match:['transport','logistics'],items:[['vehicle_trip','Vehicle trip / delivery','Record trip, route and delivery outcome'],['maintenance_job','Vehicle maintenance','Record servicing, repairs or inspection'],['work_order','Dispatch / work order','Track a transport or logistics assignment']]},{match:['construction','real estate','repair','maintenance','security'],items:[['construction_job','Project / site job','Track a project or site activity'],['maintenance_job','Maintenance job','Record repairs, inspections or scheduled maintenance'],['service_job','Client service job','Record service delivery and follow-up']]},{match:['hospitality','hotel','restaurant','catering','beauty','salon','fashion','tailoring','cleaning','events','tourism','travel'],items:[['reservation','Reservation / booking','Track a booking and its status'],['event','Event / service delivery','Record event or customer service work'],['purchase','Supplies purchase','Record supplies purchased for operations']]},{match:['finance','accounting','legal','professional services','consultancy'],items:[['case_record','Client case / matter','Track a client matter without storing unnecessary confidential details'],['client_visit','Client meeting','Record meeting follow-up'],['service_job','Professional service','Track an agreed client deliverable']]},{match:['ngo','nonprofit','church','faith','sports','fitness'],items:[['program_activity','Programme activity','Track a programme or community activity'],['event','Event / gathering','Record an event and follow-up'],['work_order','Facility / equipment task','Track a facility or equipment task']]}];return (groups.find(g=>g.match.some(x=>c.includes(x)))?.items||[['work_order','Work order','Track a job or operational task'],['service_job','Service delivery','Record a customer or internal service'],['general','General operation','Record a custom business activity']]).map(x=>({value:x[0],label:x[1],help:x[2]}))}
