  document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action;if(action==='operation-status'){const id=a.dataset.id,status=a.dataset.status;if(!id||!status)return;(async()=>{const {data,error}=await supabase.from('business_operations').update({status,updated_at:new Date().toISOString()}).eq('id',id).eq('company_id',company.id).select('id').maybeSingle();if(error||!data){toast(error?.message||'You do not have permission to update this operation.',true);return}toast('Operation status updated.');await refreshData();renderPage('operations')})()}if(action==='delete-operation'){const id=a.dataset.id;if(!id||!confirm('Delete this operation record?'))return;(async()=>{const {error}=await supabase.from('business_operations').delete().eq('id',id).eq('company_id',company.id);if(error){toast(error.message,true);return}toast('Operation record deleted.');await refreshData();renderPage('operations')})()}});
